	shortForecast: string;
	detailedForecast: string;
	isDaytime: boolean;
};

export type TidePrediction = {
	time: string;
	height: string;
	type: 'H' | 'L';
};

export type MoonForecast = {
	date: string;
	phaseName: string;
	illumination: number;
	age: number;
	nextFullMoon: string;
	nextNewMoon: string;
};

/** Feet above MLLW. Prefer ISO 8601 timestamps with an explicit offset. */
export type TidePoint = { time: string; height: string };
export type TideReading = TidePoint;

/** Current observed conditions; daily extrema use temperatureUnit and the location's calendar day. */
export type CurrentWeather = WeatherPeriod & {
	observedAt: string;
	highToday?: number;
	lowToday?: number;
};

export type WeatherBackground = 'none' | 'realistic' | 'dithered' | 'gradient';

export type ForecastEntry = { time: number; label: string; summary: string; details: string };
export type ForecastDay = { key: string; label: string; entries: ForecastEntry[] };

/** Group supplied periods in the location's calendar, without inventing missing days. */
export function forecastDays(entries: ForecastEntry[], timeZone: string): ForecastDay[] {
	const key = new Intl.DateTimeFormat('en-CA', {
		timeZone,
		year: 'numeric',
		month: '2-digit',
		day: '2-digit'
	});
	const label = new Intl.DateTimeFormat('en-US', {
		timeZone,
		weekday: 'short',
		month: 'short',
		day: 'numeric'
	});
	const days = new Map<string, ForecastDay>();
	for (const entry of entries
		.filter((e) => Number.isFinite(e.time))
		.toSorted((a, b) => a.time - b.time)) {
		const id = key.format(entry.time);
		if (!days.has(id)) days.set(id, { key: id, label: label.format(entry.time), entries: [] });
		days.get(id)!.entries.push(entry);
	}
	return [...days.values()].slice(0, 7);
}

import type { MoonForecast } from './types.js';

const synodicMonth = 29.530588853;
const knownNewMoon = Date.UTC(2000, 0, 6, 18, 14);
const dayMs = 86_400_000;

function phaseName(age: number) {
	if (age < 1.84566) return 'New Moon';
	if (age < 5.53699) return 'Waxing Crescent';
	if (age < 9.22831) return 'First Quarter';
	if (age < 12.91963) return 'Waxing Gibbous';
	if (age < 16.61096) return 'Full Moon';
	if (age < 20.30228) return 'Waning Gibbous';
	if (age < 23.99361) return 'Last Quarter';
	if (age < 27.68493) return 'Waning Crescent';
	return 'New Moon';
}

function addDays(date: Date, days: number) {
	const next = new Date(date);
	next.setUTCDate(next.getUTCDate() + days);
	return next;
}

export function getMoonForecast(date = new Date()): MoonForecast {
	const daysSince = (date.getTime() - knownNewMoon) / dayMs;
	const cycles = daysSince / synodicMonth;
	const age = (cycles - Math.floor(cycles)) * synodicMonth;
	const angle = (age / synodicMonth) * Math.PI * 2;
	const illumination = Math.round(((1 - Math.cos(angle)) / 2) * 100);
	const daysToNew = synodicMonth - age;
	const daysToFull = age < synodicMonth / 2 ? synodicMonth / 2 - age : synodicMonth * 1.5 - age;

	return {
		date: date.toISOString(),
		phaseName: phaseName(age),
		illumination,
		age: Number(age.toFixed(1)),
		nextFullMoon: addDays(date, Math.ceil(daysToFull)).toISOString(),
		nextNewMoon: addDays(date, Math.ceil(daysToNew)).toISOString()
	};
}

export const sampleMoon = getMoonForecast(new Date('2026-09-06T12:00:00-05:00'));

